import { verifyAdmin } from '../lib/auth'
import { forbidden } from 'next/navigation'

export default async function AdminPage() {
  const { isAdmin } = await verifyAdmin()

  if (!isAdmin) {
    forbidden()
  }

  return (
    <main>
      <h1>Admin Dashboard</h1>
      <p>Welcome to the admin area. You have admin privileges.</p>
    </main>
  )
}

export default function ForbiddenPage() {
  return (
    <div style={{ 
      display: 'flex', 
      flexDirection: 'column', 
      alignItems: 'center', 
      justifyContent: 'center',
      minHeight: '100vh',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <h1 style={{ fontSize: '4rem', margin: '0 0 1rem' }}>403</h1>
      <h2 style={{ fontSize: '1.5rem', margin: '0 0 1rem' }}>Access Forbidden</h2>
      <p style={{ color: '#666', maxWidth: '400px', textAlign: 'center' }}>
        You don't have permission to access this page. Please contact your administrator if you believe this is an error.
      </p>
    </div>
  )
}
